 Check(glm::length(end.position-expected)<=.0065f&&Angle(end.rotation,desired)<=.017453293f,"independent analytic world target and orientation, oblique uniformly scaled root");Check(glm::length(other.position-glm::vec3(0,2,0))<1e-5f,"shared asset instance without IK retains bind pose");
