 Check(world.RuntimeAnimation(aid)->asset==world.RuntimeAnimation(bid)->asset,"instances really share one immutable asset");Check(world.RuntimeAnimation(aid)->asset->skeleton.rest.local[1].rotation==s.rest.local[1].rotation,"IK/physics does not mutate shared rest asset");
